const input = $input.first();
const userData = input?.json;

if (!userData || !userData.id) {
  return {
    json: {
      success: false,
      error: 'User not found'
    }
  };
}

return {
  json: {
    success: true,
    user: {
      id: userData.id,
      nick: userData.nick,
      subscription_end: userData.subscription_end,
      trial_used: userData.trial_used,
      recurring: userData.recurring,
      is_premium: userData.is_premium,
      goals: {
        calories: userData.daily_calories,
        protein: userData.daily_protein,
        fat: userData.daily_fat,
        carbs: userData.daily_carbs
      }
    }
  }
};

const input = $input.first();
const mealData = input?.json;

if (!mealData || !mealData.id) {
  return {
    json: {
      success: false,
      error: 'Failed to save meal'
    }
  };
}

return {
  json: {
    success: true,
    meal: {
      id: mealData.id,
      chat_id: mealData.chat_id,
      meal_type: mealData.meal_type,
      description: mealData.description,
      calories: mealData.calories,
      protein: parseFloat(mealData.protein),
      fat: parseFloat(mealData.fat),
      carbs: parseFloat(mealData.carbs),
      created_at: mealData.created_at
    }
  }
};

const items = $input.all();
const meals = items.map(item => ({
  id: item.json.id,
  meal_type: item.json.meal_type,
  description: item.json.description,
  calories: item.json.calories || 0,
  protein: parseFloat(item.json.protein) || 0,
  fat: parseFloat(item.json.fat) || 0,
  carbs: parseFloat(item.json.carbs) || 0,
  image_url: item.json.image_url,
  created_at: item.json.created_at
}));

const totals = meals.reduce((acc, meal) => ({
  calories: acc.calories + meal.calories,
  protein: acc.protein + meal.protein,
  fat: acc.fat + meal.fat,
  carbs: acc.carbs + meal.carbs
}), { calories: 0, protein: 0, fat: 0, carbs: 0 });

return {
  json: {
    success: true,
    meals: meals,
    totals: {
      calories: Math.round(totals.calories),
      protein: Math.round(totals.protein * 10) / 10,
      fat: Math.round(totals.fat * 10) / 10,
      carbs: Math.round(totals.carbs * 10) / 10
    }
  }
};

const body = $input.first().json.body;
const period = body.period || 'week';
const interval = period === 'month' ? '30 days' : '7 days';

return {
  json: {
    chat_id: body.chat_id,
    interval: interval
  }
};

const items = $input.all();
const stats = items.map(item => ({
  date: item.json.date,
  total_calories: parseInt(item.json.total_calories) || 0,
  total_protein: parseFloat(item.json.total_protein) || 0,
  total_fat: parseFloat(item.json.total_fat) || 0,
  total_carbs: parseFloat(item.json.total_carbs) || 0,
  meals_count: parseInt(item.json.meals_count) || 0
}));

// Calculate averages
let avgCalories = 0, avgProtein = 0, avgFat = 0, avgCarbs = 0;
if (stats.length > 0) {
  avgCalories = Math.round(stats.reduce((a, s) => a + s.total_calories, 0) / stats.length);
  avgProtein = Math.round(stats.reduce((a, s) => a + s.total_protein, 0) / stats.length);
  avgFat = Math.round(stats.reduce((a, s) => a + s.total_fat, 0) / stats.length);
  avgCarbs = Math.round(stats.reduce((a, s) => a + s.total_carbs, 0) / stats.length);
}

return {
  json: {
    success: true,
    stats: stats,
    averages: {
      calories: avgCalories,
      protein: avgProtein,
      fat: avgFat,
      carbs: avgCarbs
    },
    days_tracked: stats.length
  }
};

const input = $input.first();
const goalData = input?.json;

if (!goalData) {
  return {
    json: {
      success: false,
      error: 'Failed to update goals'
    }
  };
}

return {
  json: {
    success: true,
    goals: {
      calories: goalData.daily_calories,
      protein: goalData.daily_protein,
      fat: goalData.daily_fat,
      carbs: goalData.daily_carbs
    },
    updated_at: goalData.updated_at
  }
};

